import sys

def Reduced_String(k: int, s: str) -> str:
    if k == 1:
        return ""

    stack = []

    for char in s:
        if stack and stack[-1][0] == char:
            stack[-1][1] += 1
            if stack[-1][1] == k:
                stack.pop()
        else:
            stack.append([char, 1])

    result = []
    for char, count in stack:
        result.append(char * count)

    return "".join(result)

if __name__ == "__main__":
    line1 = sys.stdin.readline().strip()
    if not line1:
        sys.exit(0)
    k = int(line1)
    s = sys.stdin.readline().strip()
    output = Reduced_String(k, s)
    sys.stdout.write(output + "\n")
